/* Shell SPA — layout full-width; home/salas centralizam só o cartão .home */

html.spartan-shell {
  width: 100%;
  min-height: 100%;
  min-height: 100dvh;
  background-color: #000;
  background-image: url("/papel-de-parede.jpg?v=12");
  background-position: center center;
  background-size: cover;
  background-repeat: no-repeat;
  background-attachment: fixed;
}

html.spartan-shell,
html.spartan-shell body {
  margin: 0;
  padding: 0;
}

/* Anula o body { display:flex; align-items:center } do spartan.css que esmagava tudo */
html.spartan-shell body {
  display: flex !important;
  flex-direction: column !important;
  align-items: stretch !important;
  justify-content: flex-start !important;
  width: 100% !important;
  max-width: none !important;
  min-height: 100vh !important;
  min-height: 100dvh !important;
  background: transparent !important;
  overflow-x: hidden !important;
}

html.spartan-shell #spartan-shell-root {
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
  width: 100%;
  min-height: 100vh;
  min-height: 100dvh;
  min-width: 0;
}

/* Barra só na sala — nunca na home/salas */
html.spartan-shell #spartan-chrome {
  display: none !important;
  flex-shrink: 0;
  width: 100%;
  box-sizing: border-box;
  align-items: center;
  gap: 0.75rem;
  padding: 0.35rem 0.75rem;
  background: #111;
  border-bottom: 1px solid #333;
  z-index: 50;
}

html.spartan-shell.spartan-in-room #spartan-chrome {
  display: flex !important;
}

#spartan-chrome a,
#spartan-chrome button {
  color: #fff;
  text-decoration: none;
  background: transparent;
  border: 1px solid #444;
  border-radius: 6px;
  padding: 0.35rem 0.75rem;
  font: inherit;
  cursor: pointer;
}

#spartan-chrome a:hover,
#spartan-chrome button:hover {
  border-color: #dc2626;
  color: #fca5a5;
}

#spartan-chrome-admin {
  margin-left: auto;
  border-color: #dc2626;
  color: #fecaca;
}

#spartan-chrome-admin[hidden] {
  display: none !important;
}

.spartan-view {
  flex: 1 1 auto;
  display: none;
  flex-direction: column;
  width: 100%;
  min-width: 0;
  min-height: 0;
  box-sizing: border-box;
}

.spartan-view.on {
  display: flex;
}

/* Home e salas: cartão centralizado, fundo em tela cheia */
html.spartan-shell #spartan-view-home.on,
html.spartan-shell #spartan-view-salas.on {
  align-items: center;
  justify-content: center;
  padding: 1.5rem 1rem 5.5rem;
}

html.spartan-shell #spartan-view-home .home,
html.spartan-shell #spartan-view-salas .home {
  flex-shrink: 0;
}

/* Sala: iframe ocupa 100% da largura */
html.spartan-shell #spartan-view-room.on {
  flex: 1 1 auto;
  min-height: 0;
}

html.spartan-shell.spartan-in-room #spartan-view-room.on {
  min-height: calc(100vh - 42px);
  min-height: calc(100dvh - 42px);
}

#spartan-room-frame {
  flex: 1 1 auto;
  width: 100% !important;
  min-width: 0;
  min-height: 0;
  height: 100%;
  border: 0;
  display: block;
  background: #000;
}

#spartan-admin-overlay {
  position: fixed;
  inset: 0;
  z-index: 10000;
  background: #0d0d0f;
  display: flex;
  flex-direction: column;
}

#spartan-admin-overlay[hidden] {
  display: none !important;
