#!/usr/bin/env python3
"""Testes do modal Configurações (HTML + CSS Spartan).

Rodar: python -m pytest tests/test_settings_ui.py -v
"""
from __future__ import annotations

import re
import unittest
from html.parser import HTMLParser
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
HTML = ROOT / "static" / "galene.html"
CSS = ROOT / "static" / "galene-spartan.css"


class _SettingsTree(HTMLParser):
    def __init__(self):
        super().__init__()
        self.stack: list[str] = []
        self.cols: dict | None = None
        self.left_children: list[str] = []
        self.right_children: list[str] = []
        self.legends: list[str] = []
        self.sound_ids: list[str] = []
        self._in_cols = False
        self._in_left = False
        self._in_right = False
        self._in_legend = False
        self._legend_buf: list[str] = []

    def handle_starttag(self, tag, attrs):
        attrs_d = dict(attrs)
        cls = attrs_d.get("class", "")
        eid = attrs_d.get("id", "")
        self.stack.append(tag)

        if tag == "div" and "spartan-settings-cols" in cls.split():
            self._in_cols = True
            self.cols = {"left": None, "right": None}
        if self._in_cols and tag == "div" and "spartan-settings-left" in cls.split():
            self._in_left = True
        if self._in_cols and tag == "div" and "spartan-settings-right" in cls.split():
            self._in_right = True
        if self._in_left and tag == "fieldset":
            self.left_children.append(cls or eid or tag)
        if self._in_right and tag == "fieldset":
            self.right_children.append(cls or eid or tag)
        if tag == "legend":
            self._in_legend = True
            self._legend_buf = []
        if eid in ("soundmensagembox", "soundentrarbox", "soundsairbox"):
            self.sound_ids.append(eid)

    def handle_endtag(self, tag):
        if tag == "legend" and self._in_legend:
            self.legends.append("".join(self._legend_buf).strip())
            self._in_legend = False
        if tag == "div":
            if self.stack and self.stack[-1] == "div":
                if self._in_right:
                    self._in_right = False
                elif self._in_left:
                    self._in_left = False
                elif self._in_cols:
                    self._in_cols = False
        if self.stack:
            self.stack.pop()

    def handle_data(self, data):
        if self._in_legend:
            self._legend_buf.append(data)


def _parse_settings() -> _SettingsTree:
    tree = _SettingsTree()
    tree.feed(HTML.read_text(encoding="utf-8"))
    return tree


class SettingsUiTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.html = HTML.read_text(encoding="utf-8")
        cls.css = CSS.read_text(encoding="utf-8")
        cls.tree = _parse_settings()

    def test_html_cache_bust_css_v87(self):
        self.assertIn("galene-spartan.css?v=87", self.html)

    def test_no_legacy_sound_sections(self):
        self.assertNotIn("Som do chat", self.html)
        self.assertNotIn("Sons da sala", self.html)
        self.assertNotIn("spartan-sound-chat", self.html)
        self.assertNotIn("spartan-sound-room", self.html)

    def test_unified_sounds_field(self):
        self.assertIn("spartan-sounds-setting", self.html)
        self.assertEqual(self.tree.sound_ids, ["soundmensagembox", "soundentrarbox", "soundsairbox"])
        self.assertIn("Sons", self.tree.legends)
        self.assertEqual(self.tree.legends.count("Sons"), 1)

    def test_column_structure(self):
        self.assertIsNotNone(self.tree.cols)
        self.assertTrue(any("spartan-set-box" in x for x in self.tree.left_children))
        self.assertTrue(any("spartan-transmit-setting" in x for x in self.tree.right_children))
        self.assertTrue(any("spartan-sounds-setting" in x for x in self.tree.right_children))
        self.assertEqual(len(self.tree.right_children), 2)

    def test_legends_only_dispositivos_transmissao_sons(self):
        wanted = {"Dispositivos", "Transmissão", "Sons"}
        found = {l for l in self.tree.legends if l in wanted}
        self.assertEqual(found, wanted)

    def test_transmissao_not_in_left_column(self):
        self.assertFalse(any("spartan-transmit-setting" in x for x in self.tree.left_children))

    def test_css_v87_flex_content_not_dual_grid(self):
        self.assertIn("spartan-v87", self.css)
        v87 = self.css.split("spartan-v87", 1)[1][:2500]
        self.assertIn("display:flex!important", v87)
        self.assertIn("flex-direction:column!important", v87)
        self.assertIn(".spartan-settings-cols", v87)
        self.assertIn("grid-template-columns:1fr 1fr!important", v87)

    def test_css_legend_inside_box(self):
        v87 = self.css.split("spartan-v87", 1)[1][:3500]
        self.assertIn(".spartan-set-box legend", v87)
        self.assertIn("display:block!important", v87)
        self.assertIn("border-bottom:1px solid", v87)
        self.assertIn("color:#fecaca!important", v87)

    def test_css_hide_legacy_sound_classes(self):
        v87 = self.css.split("spartan-v87", 1)[1][:3500]
        self.assertIn(".spartan-sound-chat", v87)
        self.assertIn("display:none!important", v87)

    def test_css_equal_height_columns(self):
        v87 = self.css.split("spartan-v87", 1)[1][:3500]
        self.assertIn("align-items:stretch!important", v87)
        self.assertIn("min-height:100%!important", v87)


class SettingsLiveTests(unittest.TestCase):
    """Opcional: valida HTML servido pelo Galene local (8443)."""

    @classmethod
    def setUpClass(cls):
        try:
            import urllib.request

            req = urllib.request.Request(
                "http://127.0.0.1:8443/galene.html",
                headers={"Cache-Control": "no-cache"},
            )
            with urllib.request.urlopen(req, timeout=3) as r:
                cls.live = r.read().decode("utf-8", errors="replace")
            cls.live_ok = True
        except Exception:
            cls.live = ""
            cls.live_ok = False

    def test_live_html_if_server_up(self):
        if not self.live_ok:
            self.skipTest("Galene não está em http://127.0.0.1:8443/")
        self.assertIn("spartan-sounds-setting", self.live)
        self.assertNotIn("Som do chat", self.live)
        self.assertIn("galene-spartan.css?v=87", self.live)


if __name__ == "__main__":
    unittest.main()

'use strict';

(function(global) {
    function fmtRemaining(info) {
        if(!info || info.remaining_s == null) return '';
        var s = Math.max(0, info.remaining_s | 0);
        var h = Math.floor(s / 3600);
        var m = Math.floor((s % 3600) / 60);
        return h + 'h ' + String(m).padStart(2, '0') + 'min';
    }

    function roomTag(s) {
        if(s.main) return 'Principal';
        if(s.ttl) return (s.open ? 'Pública' : 'Convite') + ' · 24h';
        return s.open ? 'Pública' : 'Convite';
    }

    function mount(opts) {
        opts = opts || {};
        var all = [];
        var q = '';
        var sort = 'az';
        var mainEl = document.getElementById(opts.mainId || 'spartan-salas-main');
        var permEl = document.getElementById(opts.permId || 'spartan-salas-perm');
        var tempEl = document.getElementById(opts.tempId || 'spartan-salas-temp');
        var qInput = document.getElementById(opts.qId || 'spartan-salas-q');
        var currentGroup = opts.currentGroup || '';

        function matches(s) {
            var qq = q.trim().toLowerCase();
            var t = ((s.title || s.id || '') + ' ' + (s.id || '')).toLowerCase();
            return !qq || t.indexOf(qq) >= 0;
        }

        function sortList(list, mainFirst) {
            list.sort(function(a, b) {
                if(mainFirst) {
                    if(a.main && !b.main) return -1;
                    if(b.main && !a.main) return 1;
                }
                if(sort === 'time') {
                    if(a.ttl && b.ttl) {
                        var ra = (a.remaining_s | 0);
                        var rb = (b.remaining_s | 0);
                        if(ra !== rb) return ra - rb;
                    }
                    var d = String(b.updated || '').localeCompare(String(a.updated || ''));
                    if(d) return d;
                }
                return String(a.title || a.id).localeCompare(String(b.title || b.id), 'pt');
            });
        }

        function paintRow(s, isMain) {
            var row = document.createElement(opts.link ? 'a' : 'button');
            row.className = 'sala-item' + (isMain ? ' sala-item-main' : '');
            if(opts.link) {
                row.href = opts.hrefPrefix ? (opts.hrefPrefix + encodeURIComponent(s.id)) : ('#/group/' + encodeURIComponent(s.id));
                if(opts.routeAttr) row.setAttribute('data-spartan-route', 'group:' + s.id);
            } else {
                row.type = 'button';
            }
            var rem = s.ttl ? fmtRemaining(s) : '';
            row.innerHTML = '<b></b><span class="sala-tag"></span>' +
                (rem ? '<span class="sala-rem">' + rem + '</span>' : '');
            row.querySelector('b').textContent = s.title || s.id;
            row.querySelector('.sala-tag').textContent = roomTag(s);
            if(!opts.link) {
                row.onclick = function() {
                    if(s.id === currentGroup) {
                        if(typeof opts.onClose === 'function') opts.onClose();
                        return;
                    }
                    if(typeof opts.onClose === 'function') opts.onClose();
                    if(typeof opts.onPick === 'function') opts.onPick(s.id);
                };
            }
            return row;
        }

        function fill(el, items, emptyText, isMainSlot) {
            if(!el) return;
            el.innerHTML = '';
            if(!items.length) {
                var p = document.createElement('p');
                p.className = 'salas-empty';
                p.textContent = emptyText;
                el.appendChild(p);
                return;
            }
            items.forEach(function(s) {
                el.appendChild(paintRow(s, isMainSlot && s.main));
            });
        }

        function draw() {
            var main = null;
            var permanent = [];
            var temporary = [];
            all.forEach(function(s) {
                if(!matches(s)) return;
                if(s.main) main = s;
                else if(s.ttl) temporary.push(s);
                else permanent.push(s);
            });
            sortList(permanent, false);
            sortList(temporary, false);
            if(mainEl) {
                mainEl.innerHTML = '';
                if(main) mainEl.appendChild(paintRow(main, true));
                else {
                    var p = document.createElement('p');
                    p.className = 'salas-empty';
                    p.textContent = 'Sala principal não listada.';
                    mainEl.appendChild(p);
                }
            }
            fill(permEl, permanent, 'Nenhuma sala permanente extra.');
            fill(tempEl, temporary, 'Nenhuma sala temporária ativa.');
        }

        function load() {
            if(mainEl) mainEl.innerHTML = '<p class="salas-empty">Carregando…</p>';
            if(permEl) permEl.innerHTML = '';
            if(tempEl) tempEl.innerHTML = '';
            fetch('/spartan-api/rooms' + (opts.all ? '?all=0' : ''))
                .then(function(r) { return r.json(); })
                .then(function(data) {
                    all = data || [];
                    draw();
                })
                .catch(function() {
                    if(mainEl) mainEl.innerHTML = '<p class="salas-empty">Não deu para listar as salas.</p>';
                });
        }

        if(qInput) {
            qInput.addEventListener('input', function(e) {
                q = e.target.value;
                draw();
            });
        }
        document.querySelectorAll(opts.sortSelector || '#spartan-salas-overlay .sort-btn, .salas-tools [data-sort]').forEach(function(btn) {
            btn.onclick = function() {
                sort = btn.getAttribute('data-sort') || 'az';
                document.querySelectorAll(opts.sortSelector || '#spartan-salas-overlay .sort-btn, .salas-tools [data-sort]').forEach(function(x) {
                    x.classList.toggle('on', x === btn);
                });
                draw();
            };
        });

        return {load: load, draw: draw};
    }

    global.SpartanSalas = {mount: mount};
})(typeof window !== 'undefined' ? window : globalThis);

