function spartanSalasRoomBind() {
    const PAGE = 5;
    let all = [], q = '', sort = 'az', page = 0, bound = false;
    const overlay = document.getElementById('spartan-salas-overlay');
    const list = document.getElementById('spartan-salas-list');
    const pager = document.getElementById('spartan-salas-pager');
    const pageLab = document.getElementById('spartan-salas-page');
    const btn = document.getElementById('spartan-salas-btn');
    const qInput = document.getElementById('spartan-salas-q');
    if(!overlay || !list || !btn)
        return;
    if(!spartanInShell()) {
        btn.hidden = true;
        return;
    }
    btn.hidden = false;

    function filtered() {
        let qq = q.trim().toLowerCase();
        let items = all.filter(function(s) {
            if(s.ttl)
                return false;
            let t = ((s.title || s.id || '') + ' ' + (s.id || '')).toLowerCase();
            return !qq || t.indexOf(qq) >= 0;
        });
        items.sort(function(a, b) {
            if(a.main && !b.main) return -1;
            if(b.main && !a.main) return 1;
            if(sort === 'time') {
                let d = String(b.updated || '').localeCompare(String(a.updated || ''));
                if(d) return d;
            }
            return String(a.title || a.id).localeCompare(String(b.title || b.id), 'pt');
        });
        return items;
    }

    function draw() {
        let items = filtered();
        let pages = Math.max(1, Math.ceil(items.length / PAGE));
        if(page > pages - 1) page = pages - 1;
        if(page < 0) page = 0;
        list.innerHTML = '';
        items.slice(page * PAGE, page * PAGE + PAGE).forEach(function(s) {
            let row = document.createElement('button');
            row.type = 'button';
            row.className = 'sala-item';
            row.innerHTML = '<b></b><span class="sala-tag"></span>';
            row.querySelector('b').textContent = s.title || s.id;
            row.querySelector('.sala-tag').textContent = s.main ? 'Principal' : 'Convite';
            row.onclick = function() {
                if(s.id === group) {
                    closeSalas();
                    return;
                }
                closeSalas();
                spartanGoRoom(s.id);
            };
            list.appendChild(row);
        });
        if(!items.length)
            list.textContent = 'Nenhuma sala.';
        let many = items.length > PAGE;
        pager.hidden = !many;
        if(many)
            pageLab.textContent = (page + 1) + ' / ' + pages;
        let prev = document.getElementById('spartan-salas-prev');
        let next = document.getElementById('spartan-salas-next');
        if(prev) prev.disabled = page <= 0;
        if(next) next.disabled = page >= pages - 1;
    }

    function loadSalas() {
        list.textContent = 'Carregando…';
        fetch('/spartan-api/rooms')
            .then(function(r) { return r.json(); })
            .then(function(data) {
                all = data || [];
                draw();
            })
            .catch(function() {
                list.textContent = 'Não deu para listar as salas.';
            });
    }

    function openSalas() {
        overlay.hidden = false;
        loadSalas();
    }

    function closeSalas() {
        overlay.hidden = true;
    }

    if(!bound) {
        bound = true;
        btn.onclick = openSalas;
        document.getElementById('spartan-salas-close').onclick = closeSalas;
        document.getElementById('spartan-salas-back').onclick = closeSalas;
        overlay.addEventListener('click', function(e) {
            if(e.target === overlay)
                closeSalas();
        });
        if(qInput) {
            qInput.oninput = function(e) {
                q = e.target.value;
                page = 0;
                draw();
            };
        }
        document.getElementById('spartan-salas-prev').onclick = function() {
            page--;
            draw();
        };
        document.getElementById('spartan-salas-next').onclick = function() {
            page++;
            draw();
        };
        document.querySelectorAll('#spartan-salas-overlay .sort-btn').forEach(function(sortBtn) {
            sortBtn.onclick = function() {
                sort = sortBtn.getAttribute('data-sort');
                page = 0;
                document.querySelectorAll('#spartan-salas-overlay .sort-btn').forEach(function(x) {
                    x.classList.toggle('on', x === sortBtn);
                });
                draw();
            };
        });
        document.addEventListener('keydown', function(e) {
            if(e.key === 'Escape' && !overlay.hidden)
                closeSalas();
        });
    }
}

